254	func TestCompactConcurrent(t *testing.T) {
255		s := openStore(t, tempDir(t))
256	
257		const writers = 4
258		const compactors = 2
259		const iterations = 100
260	
261		var wg sync.WaitGroup
262		for w := 0; w < writers; w++ {
263			wg.Add(1)
264			go func(w int) {
265				defer wg.Done()
266				key := fmt.Sprintf("k%d", w)
267				for i := 0; i < iterations; i++ {
268					v := []byte(fmt.Sprintf("%d-%d", w, i))
269					if err := s.Put(key, v); err != nil {
270						t.Errorf("put: %v", err)
271						return
272					}
273					if i%17 == 0 {
274						if err := s.Delete(key); err != nil {
275							t.Errorf("delete: %v", err)
276							return
277						}
278					}
279				}
280			}(w)
281		}
282		for c := 0; c < compactors; c++ {
283			wg.Add(1)
284			go func() {
285				defer wg.Done()
286				for i := 0; i < 20; i++ {
287					if err := s.Compact(); err != nil {
288						t.Errorf("compact: %v", err)
289						return
290					}
291				}
292			}()
293		}
294	
295		stop := make(chan struct{})
296		var readers sync.WaitGroup
297		readers.Add(1)
298		go func() {
299			defer readers.Done()
300			for {
301				select {
302				case <-stop:
303					return
304				default:
305				}
306				snap, err := s.Snapshot()
307				if err != nil {
308					if errors.Is(err, fs.ErrClosed) {
309						return
310					}
311					t.Errorf("snapshot: %v", err)
312					return
313				}
314				// Two passes over the fixed view must agree exactly.
315				first := map[string]string{}
316				for w := 0; w < writers; w++ {
317					if v, ok := snap.Get(fmt.Sprintf("k%d", w)); ok {
318						first[fmt.Sprintf("k%d", w)] = string(v)
319					}
320				}
321				for k, want := range first {
322					if got, ok := snap.Get(k); !ok || string(got) != want {
323						t.Errorf("snapshot view of %s changed across compaction", k)
324					}
325				}
326				snap.Close()
327			}
328		}()
329	
330		wg.Wait()
331		close(stop)
332		readers.Wait()
333	
334		if err := s.Compact(); err != nil {
335			t.Fatalf("final compact: %v", err)
336		}
337	}
