339	func TestCompactStaleTempAfterCrash(t *testing.T) {
340		dir := tempDir(t)
341		s := openStore(t, dir)
342		if err := s.Put("keep", []byte("value")); err != nil {
343			t.Fatal(err)
344		}
345		if _, err := s.Snapshot(); err != nil {
346			t.Fatal(err)
347		}
348		if err := s.Close(); err != nil {
349			t.Fatal(err)
350		}
351	
352		// Simulate a crash mid-compaction: a half-built replacement file exists
353		// next to an intact wal.log. Reopen must ignore the temp, need no second
354		// compaction, and recover a complete committed state.
355		if err := os.WriteFile(filepath.Join(dir, compactTmpName), []byte("partial garbage"), 0o600); err != nil {
356			t.Fatal(err)
357		}
358	
359		s2, err := Open(dir)
360		if err != nil {
361			t.Fatalf("reopen with stale temp: %v", err)
362		}
363		defer s2.Close()
364		if got, ok, _ := s2.Get("keep"); !ok || string(got) != "value" {
365			t.Fatalf("value lost with stale temp: %q ok=%v", got, ok)
366		}
367		if n := s2.Stats().Snapshots; n != 1 {
368			t.Fatalf("snapshot count with stale temp: %d, want 1", n)
369		}
370		if _, err := os.Stat(filepath.Join(dir, compactTmpName)); !errors.Is(err, fs.ErrNotExist) {
371			t.Fatalf("stale temp not removed on open: %v", err)
372		}
373	
374		// Commits and a fresh compaction work immediately, with no repair step.
375		if err := s2.Put("after", []byte("x")); err != nil {
376			t.Fatal(err)
377		}
378		if err := s2.Compact(); err != nil {
379			t.Fatalf("compact after crash recovery: %v", err)
380		}
381		if err := s2.Close(); err != nil {
382			t.Fatal(err)
383		}
384		s3, err := Open(dir)
385		if err != nil {
386			t.Fatal(err)
387		}
388		defer s3.Close()
389		if got, ok, _ := s3.Get("after"); !ok || string(got) != "x" {
390			t.Fatalf("post-recovery commit lost: %q ok=%v", got, ok)
391		}
392	}
