95	// regular file rather than a directory returns an error wrapping
96	// fs.ErrInvalid.
97	func Open(dir string) (*Store, error) {
98		info, err := os.Stat(dir)
99		if err == nil {
100			if !info.IsDir() {
101				return nil, errNotDir
102			}
103		} else {
104			if !errors.Is(err, fs.ErrNotExist) {
105				return nil, err
106			}
107			if err := os.MkdirAll(dir, 0o700); err != nil {
108				return nil, err
109			}
110		}
111	
112		// A replacement log from a compaction killed before its rename can never
113		// be complete state of record; the old wal.log is. Drop the stale file.
114		if err := removeStaleCompact(dir); err != nil {
115			return nil, err
116		}
117		// Likewise, a checkpoint temp from a freeze killed before its rename can
118		// never be a complete checkpoint; the live checkpoint (if any) is.
119		if err := removeStaleCheckpointTemp(dir); err != nil {
120			return nil, err
121		}
122	
123		latest, replaySeq, snapshotCount, validSize, err := recoverState(dir)
124		if err != nil {
125			return nil, err
126		}
127	
128		wal, err := openWALWriter(dir, validSize)
129		if err != nil {
130			return nil, err
131		}
132	
133		s := &Store{dir: dir, wal: wal, cursors: make(map[*Cursor]struct{}), nextSeq: replaySeq}
134		s.snapshots.Store(snapshotCount)
135		s.current.Store(&latest)
136		return s, nil
137	}
138	
139	// recoverState rebuilds the committed state, using a complete checkpoint plus
140	// only the log frames that follow it whenever a usable checkpoint exists. A
141	// checkpoint that is missing, truncated, corrupt, written by an unknown
142	// version, or inconsistent with the log is rejected wholesale — never half
143	// applied — and recovery falls back to replaying wal.log from the beginning,
144	// which always reconstructs the complete committed state. A directory with no
145	// checkpoint therefore reopens exactly as before, and the first checkpoint
146	// upgrades it to the checkpoint layout with no separate migration.
147	func recoverState(dir string) (view, uint64, uint64, int64, error) {
148		var walSize int64
149		if info, err := os.Stat(dir + string(os.PathSeparator) + walName); err == nil {
150			walSize = info.Size()
151		} else if !errors.Is(err, fs.ErrNotExist) {
152			return nil, 0, 0, 0, err
153		}
154	
155		cp, cpErr := loadCheckpoint(dir, walSize)
156		if cpErr == nil {
157			latest := make(view, len(cp.entries))
158			for i := range cp.entries {
159				e := &cp.entries[i]
160				latest[e.key] = &node{value: cloneBytes(e.value), present: true, seq: e.seq}
161			}
162			var replaySeq = cp.nextSeq
163			validSize, snapshotCount, tailErr := replayWALFrom(dir, cp.walOffset,
164				func(op byte, key string, value []byte, seq uint64) {
165					if seq == 0 {
166						// Defensive: a post-checkpoint tail only ever carries Seq
167						// records, but number any legacy frame in commit order
168						// rather than resetting the watermark.
169						replaySeq++
170						seq = replaySeq
171					} else if seq > replaySeq {
172						replaySeq = seq
173					}
174					switch op {
175					case opPut, opPutSeq:
176						latest[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: latest[key]}
177					case opDelete, opDeleteSeq:
178						latest[key] = &node{present: false, seq: seq, older: latest[key]}
179					}
180				})
181			if tailErr == nil {
182				// Meta frames in the tail carry absolute cumulative counts; absent
183				// any, the checkpoint's frozen count is current.
184				if snapshotCount < cp.snapshotCount {
185					snapshotCount = cp.snapshotCount
186				}
187				return latest, replaySeq, snapshotCount, validSize, nil
188			}
189			// The checkpoint did not pair with a usable tail; reject it and
190			// recover from the log alone.
191			cpErr = tailErr
192		}
193	
194		// Full-log recovery. A torn/corrupt WAL still yields its complete
195		// committed prefix here, so this path is always the authoritative
196		// fallback the rejection contract relies on.
197		latest := make(view)
198		var replaySeq uint64
199		validSize, snapshotCount, err := replayWAL(dir, func(op byte, key string, value []byte, seq uint64) {
200			// Legacy records (written before sequence numbers existed) carry no
201			// seq; replay order is commit order, so number them sequentially.
202			if seq == 0 {
203				replaySeq++
204				seq = replaySeq
205			} else if seq > replaySeq {
206				replaySeq = seq
